pub enum VmError {
    DivideByZero { ip: usize },
    StackUnderflow { ip: usize },
    UndefinedName { ip: usize, name: String },
}

impl fmt::Display for VmError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            VmError::DivideByZero { ip } => write!(f, "divide by zero at {ip:04}"),
            VmError::StackUnderflow { ip } => write!(f, "stack underflow at {ip:04}"),
            VmError::UndefinedName { ip, name } => write!(f, "undefined name `{name}` at {ip:04}"),
        }
    }
}

impl std::error::Error for VmError {}

#[derive(Debug, Default)]
pub struct Vm {
    stack: Vec<f64>,
}

impl Vm {
    pub fn new() -> Vm {
        Vm { stack: Vec::new() }
    }

    fn pop(&mut self, ip: usize) -> Result<f64, VmError> {
        let v = self.stack.pop()?;
        Ok(v)
    }

    pub fn run(&mut self, chunk: &Chunk) -> Result<f64, VmError> {
        let mut ip = 0;
        while ip < chunk.code.len() {
            let here = ip;
            let op = chunk.code[ip];
            ip += 1;
            match op {
                Op::Const(k) => self.stack.push(chunk.consts[k]),
                Op::Add => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a + b);
                }
                Op::Sub => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a - b);
                }
                Op::Mul => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a * b);
                }
                Op::Div => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a / b);
                }
                Op::Neg => {
                    let a = self.pop(here)?;
                    self.stack.push(-a);
                }
                Op::Return => return self.pop(here),
            }
        }
        self.pop(ip)
    }
}

