                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    if b == 0.0 {
                        return Err(VmError::DivideByZero { ip: here });
                    }
                    self.stack.push(a / b);
                }
                Op::Neg => {
                    let a = self.pop(here)?;
                    self.stack.push(-a);
                }
                Op::Return => return self.pop(here),
            }
        }
        self.pop(ip)
    }
