#[derive(Debug, Default)]
pub struct Vm {
    stack: Vec<f64>,
    globals: HashMap<String, f64>,
}

impl Vm {
    pub fn new() -> Vm {
        Vm { stack: Vec::new(), globals: HashMap::new() }
    }

    fn pop(&mut self, ip: usize) -> Result<f64, VmError> {
        match self.stack.pop() {
            Some(v) => Ok(v),
            None => Err(VmError::StackUnderflow { ip }),
        }
    }

    pub fn run(&mut self, chunk: &Chunk) -> Result<f64, VmError> {
        let mut ip = 0;
        while ip < chunk.code.len() {
            let here = ip;
            let op = chunk.code[ip];
            ip += 1;
            match op {
                Op::Const(k) => self.stack.push(chunk.consts[k]),
                Op::Add => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a + b);
                }
                Op::Sub => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a - b);
                }
                Op::Mul => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    self.stack.push(a * b);
                }
                Op::Div => {
                    let b = self.pop(here)?;
                    let a = self.pop(here)?;
                    if b == 0.0 {
                        return Err(VmError::DivideByZero { ip: here });
                    }
                    self.stack.push(a / b);
                }
                Op::Neg => {
                    let a = self.pop(here)?;
                    self.stack.push(-a);
                }
                Op::GetGlobal(k) => match self.globals.get(&chunk.names[k]) {
                    Some(v) => self.stack.push(*v),
                    None => {
                        return Err(VmError::UndefinedName {
                            ip: here,
                            name: chunk.names[k].clone(),
                        })
                    }
                },
                Op::SetGlobal(k) => {
                    let v = self.pop(here)?;
                    self.globals.insert(chunk.names[k], v);
                }
                Op::Pop => {
                    self.pop(here)?;
                }
                Op::Return => return self.pop(here),
            }
        }
        self.pop(ip)
    }
}

