    let mut c = Chunk::new();
    let two = c.add_const(2.0);
    let three = c.add_const(3.0);
    let four = c.add_const(4.0);
    c.push(Op::Const(two));
    c.push(Op::Const(three));
    c.push(Op::Const(four));
    c.push(Op::Mul);
    c.push(Op::Add);
    c.push(Op::Return);
